  'use strict';

  // Trunic glyph id -> ARPAbet. The r-coloured chart vowels are a vowel plus R.
  // The chart's "ah" (swan) is one glyph for the cot and caught vowels, which the
  // dictionary keeps apart (AA, AO), so it stands for either at no cost.
  var ARPABET = {
    // vowels
    a: ['AE'], ar: ['AA', 'R'], ah: ['AA/AO'], ay: ['EY'], e: ['EH'], ee: ['IY'],
    eer: ['IH', 'R'], eh: ['AH'], ere: ['EH', 'R'], i: ['IH'], ie: ['AY'], ir: ['ER'],
    oh: ['OW'], oi: ['OY'], oo: ['UW'], ou: ['UH'], ow: ['AW'], ore: ['AO', 'R'],
    // consonants
    b: ['B'], ch: ['CH'], d: ['D'], f: ['F'], g: ['G'], h: ['HH'], j: ['JH'], k: ['K'],
    l: ['L'], m: ['M'], n: ['N'], ng: ['NG'], p: ['P'], r: ['R'], s: ['S'], sh: ['SH'],
    t: ['T'], th: ['TH'], dh: ['DH'], v: ['V'], w: ['W'], y: ['Y'], z: ['Z'], zh: ['ZH']
  };

  var VOWEL_SYMBOLS = ['AA', 'AE', 'AH', 'AO', 'AW', 'AY', 'EH', 'ER', 'EY', 'IH', 'IY', 'OW', 'OY', 'UH', 'UW'];

  // Vowels that are easy to confuse, with the cost of swapping them (tenths).
  var NEAR_VOWELS = [
    ['AA', 'AO', 3], ['IH', 'IY', 3], ['UH', 'UW', 3], ['AH', 'ER', 3],
    ['EH', 'AE', 4], ['EH', 'IH', 4], ['AH', 'IH', 4], ['AH', 'UH', 4], ['AO', 'OW', 4],
    ['AH', 'EH', 5], ['AH', 'AA', 5], ['AH', 'AO', 5], ['AE', 'AA', 5], ['EY', 'EH', 5],
    ['EY', 'IY', 5], ['OY', 'AO', 5], ['UH', 'OW', 5], ['AW', 'AA', 5], ['AY', 'AA', 5]
  ];

  var EITHER = { 'AA/AO': ['AA', 'AO'] };

  var INDEL = 10, INDEL_SCHWA = 6, SUBSTITUTE = 10, CROSS_CLASS = 15, SCHWA_SWAP = 3;

  // Words that win a tie against the more frequent word they sound like
  // ("hole" over "whole", "flee" over "flea", "gnaw" over "na"), because the
  // frequency order picks the wrong one. Keep this short: it only settles exact homophones.
